+const result = document.getElementById('quiz-result');
+
+const questions = [
+  { name: 'q1', answerCount: 2 },
+  { name: 'q2', answerCount: 3 },
+  { name: 'q3', answerCount: 3 },
+];
+
+form.addEventListener('submit', (event) => {
+  event.preventDefault();
+
+  const totalCorrect = questions.reduce((sum, question) => {
+    const selected = [...form.querySelectorAll(`input[name="${question.name}"]:checked`)];
+    const correct = selected.filter((input) => input.dataset.correct === 'true').length;
+    const incorrect = selected.length - correct;
+
+    return sum + Math.max(0, correct - incorrect);
+  }, 0);
+
+  const maxScore = questions.reduce((sum, question) => sum + question.answerCount, 0);
+  result.textContent = `You scored ${totalCorrect} out of ${maxScore}.`;
+});
